    static boolean developedNpc(NativeSession.State state){var npc=state.objects().stream().filter(a->a.owner()==3).toList();return npc.stream().anyMatch(a->a.template().equals("ChinaSupplyCenter")&&a.constructionPercent()<0)&&npc.stream().anyMatch(a->a.template().equals("ChinaBarracks")&&a.constructionPercent()<0)&&npc.stream().anyMatch(a->a.template().equals("ChinaInfantryRedguard"));}
    static void beginDual(Minecraft mc){listener=CompletableFuture.supplyAsync(()->{try{var s=mc.getSingleplayerServer();int port;try(var socket=new java.net.ServerSocket(0,1,java.net.InetAddress.getLoopbackAddress())){port=socket.getLocalPort();}s.setUsesAuthentication(false);s.getConnection().startTcpServerListener(java.net.InetAddress.getLoopbackAddress(),port);var l=s.getLevel(GeneralsMod.ARENA);l.setBlock(new BlockPos(96,64,0),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);l.setBlock(new BlockPos(0,64,0),SiteBlocks.START.defaultBlockState(),3);l.setBlock(new BlockPos(96,64,0),SiteBlocks.START.defaultBlockState(),3);WorldSiteStore.get(l).putStart(new BlockPos(0,64,0),0,"",0,-1);WorldSiteStore.get(l).putStart(new BlockPos(96,64,0),1,"",1,-1);return port;}catch(Exception error){throw new CompletionException(error);}},mc.getSingleplayerServer());next(10);}
    static void damageBuildings(Minecraft mc,int owner){mc.getSingleplayerServer().execute(()->{try{var field=NativeNetworkServer.class.getDeclaredField("match");field.setAccessible(true);var match=(NativeServerMatch)field.get(null);var session=match.session();var state=session.read();int count=0;for(var a:state.objects())if(a.owner()==owner&&a.structure()){session.send("HOST_DAMAGE "+a.id()+" 1000000 0");count++;}if(count==0)throw new IllegalStateException("Missing target buildings");}catch(Exception error){throw new RuntimeException(error);}});}
    static void chooseHost(){NativeNetworkClient.request("choose",j->{j.addProperty("faction","FactionAmerica");j.addProperty("color",0);j.addProperty("team",0);j.addProperty("start",-1);});}
    static net.minecraft.world.phys.Vec3 outward(NativeWorldView v,NativeSession.Actor unit){var base=v.state.objects().stream().filter(a->a.owner()==unit.owner()&&a.structure()).findFirst().orElseThrow();double dx=unit.x()-base.x(),dz=unit.y()-base.y(),length=Math.max(.01,Math.hypot(dx,dz));return v.origin.world(unit.x(),unit.y(),unit.z()).add(dx/length*7,0,dz/length*7);}
    static void next(int n){stage=n;age=0;}
    static void launchPeer(int port)throws Exception{
        var args=new ArrayList<>(java.lang.management.ManagementFactory.getRuntimeMXBean().getInputArguments());args.removeIf(a->a.startsWith("-Dgeneralsmc.nativeNetworkBench=")||a.startsWith("-Dgeneralsmc.nativeNetworkDual="));
        args.add("-Dgeneralsmc.nativeNetworkBench=false");args.add("-Dgeneralsmc.nativeNetworkPeer=true");args.add("-Dgeneralsmc.nativeRoot="+root);args.add("-Dgeneralsmc.peerPort="+port);args.add("-cp");args.add(System.getProperty("java.class.path"));args.add("net.fabricmc.devlaunchinjector.Main");var dir=root.resolve("minecraft-peer");Files.createDirectories(dir);String id=UUID.nameUUIDFromBytes("OfflinePlayer:BridgePeer".getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();args.addAll(List.of("--username","BridgePeer","--uuid",id,"--gameDir",dir.toString(),"--width","960","--height","600"));
        var argFile=root.resolve("peer-java.args");var encoded=new StringBuilder();for(String arg:args)encoded.append('"').append(arg.replace("\\","\\\\").replace("\"","\\\"")).append("\"\n");Files.writeString(argFile,encoded.toString());
        peerProcess=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/javaw.exe").toString(),"@"+argFile).directory(dir.toFile()).redirectErrorStream(true).redirectOutput(root.resolve("peer-minecraft.log").toFile()).start();var owned=peerProcess;Runtime.getRuntime().addShutdownHook(new Thread(()->{if(owned.isAlive())owned.destroyForcibly();},"zhmc-owned-peer-exit"));

    }
    static void finish(Minecraft mc,String result,String error){done=true;try{var r=new LinkedHashMap<String,Object>();r.put("result",result);r.put("checks",checks);r.put("stage",stage);r.put("firstMovementMillis",responseMillis);r.put("repeatedMovementMillis",NativeLatencyBench.millis);r.put("root",String.valueOf(root));r.put("world",world);if(Files.exists(root.resolve("peer-latency.json")))r.put("injectedLatency",com.google.gson.JsonParser.parseString(Files.readString(root.resolve("peer-latency.json"))));r.put("scope",Boolean.getBoolean("generalsmc.nativeNetworkDual")?"Two real Minecraft clients over an owned loopback TCP server, original authority plus two original graphical peers, own armies, marker permissions and foreign-order rejection. Independent NPC progression is recorded separately. Cooperative mode is tested only when its shared-vision/NPC checks are present. Full gameplay/network parity is not claimed.":"One real Minecraft client plus integrated server, a shared authoritative original process (or an explicitly forced separate peer), real Fabric packets and NPC. Does not prove a second Minecraft client or PvP.");if(error!=null)r.put("error",error);Files.writeString(Path.of(System.getProperty("generalsmc.evidence","evidence"),"native-network-client-tests.json"),GeneralsMod.JSON.toJson(r));if(root!=null)Files.writeString(root.resolve("peer-exit"),"stop");}catch(Exception e){GeneralsMod.LOG.error("Network evidence failed",e);}NativeNetworkClient.leave();mc.stop();}
